import{_ as t,o as n,c as s,a4 as a}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0012 — Passages RAG reconstitués depuis l'index lexical, jamais stockés une seconde fois","description":"Extrait de docs/adr/0012-passages-rag-reconstitues-depuis-l-index-lexical.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0012 — Passages RAG reconstitués depuis l'index lexical, jamais stockés une seconde fois","description":"Extrait de docs/adr/0012-passages-rag-reconstitues-depuis-l-index-lexical.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0012-passages-rag-reconstitues-depuis-l-index-lexical.md","filePath":"developpeurs/adr/0012-passages-rag-reconstitues-depuis-l-index-lexical.md"}`),i={name:"developpeurs/adr/0012-passages-rag-reconstitues-depuis-l-index-lexical.md"};function o(r,e,d,c,u,l){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0012--passages-rag-reconstitués-depuis-lindex-lexical-jamais-stockés-une-seconde-fois" tabindex="-1">ADR-0012 — Passages RAG reconstitués depuis l&#39;index lexical, jamais stockés une seconde fois <a class="header-anchor" href="#adr-0012--passages-rag-reconstitués-depuis-lindex-lexical-jamais-stockés-une-seconde-fois" aria-label="Permalink to &quot;ADR-0012 — Passages RAG reconstitués depuis l&#39;index lexical, jamais stockés une seconde fois {#adr-0012--passages-rag-reconstitués-depuis-lindex-lexical-jamais-stockés-une-seconde-fois}&quot;">​</a></h1><p><strong>Date :</strong> 20 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §14.5, §14.6, §14.9.3, §16.2 ; plan d&#39;action agile §5 (jalon M8b), §9 (risque « fuite de contexte entre organisations dans le RAG »)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le modèle de données du CDC (§14.5) définit <code>ai_embeddings</code> comme portant un vecteur, une dimension, une empreinte de contenu (<code>content_hash</code>) et l&#39;identifiant de l&#39;objet source — <strong>pas le texte du fragment</strong>. C&#39;est cohérent avec le reste du socle : <code>ai_jobs</code> ne conserve aucun contenu, et le CMS refuse de constituer un second entrepôt de ses propres contenus au motif que l&#39;IA en aurait besoin.</p><p>Or une réponse documentée (RAG, §14.9.3) suppose exactement cela : retrouver le <em>texte</em> des fragments voisins d&#39;une question pour l&#39;assembler en contexte. La table ne le contient pas ; il faut donc décider d&#39;où il vient.</p><p>La question n&#39;est pas seulement technique. Un passage stocké à côté du vecteur est un exemplaire de plus du contenu : à sauvegarder, à purger, à exporter sur demande de droit d&#39;accès, et à maintenir cohérent avec l&#39;original. Un passage périmé cité par une réponse est, lui, une réponse fausse qui a toutes les apparences d&#39;une réponse sourcée.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Aucun passage n&#39;est stocké.</strong> Le texte cité par une réponse est <strong>reconstitué à la lecture</strong>, en refragmentant la source telle qu&#39;elle est <em>au moment de la question</em>, avec le même découpage déterministe que celui utilisé à l&#39;indexation (<code>app/ai_editorial/chunking.py</code>). La source est lue dans <code>search_index</code> — l&#39;index lexical d&#39;E3, qui porte déjà le titre, le corps et le texte extrait des documents (§16.2) — et <strong>toujours avec le filtre de l&#39;organisation</strong>.</p><p>Trois conséquences en découlent, et ce sont elles qui motivent la décision :</p><ol><li>Un contenu corrigé depuis sa vectorisation est cité dans sa version corrigée. Le vecteur peut être un peu périmé — c&#39;est ce que <code>content_hash</code> sert à détecter, et ce qu&#39;une réindexation corrige — mais la <strong>citation</strong> ne l&#39;est jamais.</li><li>Un contenu retiré de l&#39;index cesse d&#39;être citable immédiatement, sans attendre le nettoyage de l&#39;index vectoriel.</li><li>La résolution du passage constitue une <strong>seconde barrière d&#39;isolation multi-organisation</strong>, indépendante de la première. Si un vecteur venait, par un défaut quelconque, à désigner l&#39;objet d&#39;une autre collectivité, il ne produirait aucun passage : la relecture de <code>search_index</code> est filtrée par organisation, et un fragment non résolu n&#39;entre pas dans le contexte envoyé au modèle. Le plan d&#39;action §9 exige un test dédié sur ce risque ; il y en a deux, un par barrière.</li></ol><p>Le point d&#39;extension <code>PassageResolver</code> reste ouvert pour un déploiement qui indexerait des sources hors <code>search_index</code>, mais le résolveur par défaut est celui décrit ci-dessus.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Ajouter une colonne <code>content</code> à <code>ai_embeddings</code></strong></td><td>Écartée : duplique les contenus du CMS dans une table technique, y compris des fragments susceptibles de porter des données personnelles (une demande SVE indexée), avec un cycle de vie et une purge à tenir en parallèle de ceux du contenu d&#39;origine. Et une citation figée à la date de vectorisation, présentée comme une source, est plus trompeuse qu&#39;une absence de citation.</td></tr><tr><td><strong>Table dédiée <code>rag_passages</code></strong></td><td>Écartée pour les mêmes raisons, avec en plus une migration et une table de plus à maintenir cohérente avec <code>content_entries</code> et <code>search_index</code> — trois sources de vérité pour un même texte.</td></tr><tr><td><strong>Exiger un résolveur fourni par l&#39;appelant, sans défaut</strong></td><td>Écartée comme comportement par défaut : chaque appelant aurait réimplémenté le découpage, donc divergé de celui de l&#39;indexation, et le rang d&#39;un fragment aurait fini par désigner un passage différent à l&#39;écriture et à la lecture. Conservée comme point d&#39;extension explicite.</td></tr><tr><td><strong>Ne pas citer de sources du tout</strong></td><td>Écartée : une réponse non sourcée n&#39;est pas une réponse documentée, et le §14.9.3 demande précisément l&#39;inverse.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li><code>ai_embeddings</code> reste ce que le CDC en fait : un index, pas un entrepôt.</li><li>Les citations sont à jour par construction, et la suppression d&#39;un contenu suffit à le rendre incitable.</li><li>Une barrière d&#39;isolation multi-organisation supplémentaire, obtenue sans code dédié.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Les paramètres de fragmentation deviennent un contrat de l&#39;index.</strong> Changer la taille d&#39;un fragment ou son recouvrement désaligne le rang (<code>chunk_index</code>) et le passage qu&#39;il désigne, silencieusement — exactement le piège que l&#39;ADR-0004 décrit pour le modèle d&#39;embedding. Un tel changement doit donc être traité comme une réindexation, et l&#39;Epic E13 (Recherche complète), qui portera la réindexation à l&#39;échelle, doit le prévoir explicitement.</li><li>Seuls les objets présents dans <code>search_index</code> sont citables. C&#39;est acceptable — un contenu qu&#39;on ne peut pas retrouver par mots-clés n&#39;a pas de raison d&#39;être cité par une réponse — mais cela lie le RAG à l&#39;index lexical, et il faut le savoir.</li><li>La résolution coûte une lecture par voisin. Le nombre de voisins est borné (<code>top_k</code> ≤ 20) ; si cela devenait un coût réel, la parade est une lecture groupée, pas un stockage des passages.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[ ] Epic E13 (Recherche complète) : traiter tout changement des paramètres de fragmentation comme une réindexation, au même titre qu&#39;un changement de modèle d&#39;embedding (ADR-0004).</li></ul>',20)])])}const g=t(i,[["render",o]]);export{m as __pageData,g as default};
